import{z as s,x as o,o as i,c as d,q as n,j as r,D as e,d as l,s as B,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"参数正则：EWC 一族","description":"","frontmatter":{"title":"参数正则：EWC 一族","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/continual-ewc-family.md","filePath":"llm/continual-ewc-family.md","lastUpdated":1791063341000}'),p={name:"llm/continual-ewc-family.md"};function h(m,a,C,c,F,u){const t=o("Mermaid");return i(),d("div",null,[a[2]||(a[2]=n('<h1 id="参数正则-ewc-一族" tabindex="-1">参数正则：EWC 一族 <a class="header-anchor" href="#参数正则-ewc-一族" aria-label="Permalink to &quot;参数正则：EWC 一族&quot;">​</a></h1><div class="epigraph"><p>一个参数重不重要，不看它的绝对值，看曲率：动它一格，旧任务的损失涨多少。</p><footer>—— Kirkpatrick 等，Elastic Weight Consolidation，PNAS 2017</footer></div><p><a href="/llm/continual-forgetting-mechanism">上一课</a>把遗忘拆成方向与步长两个几何量，并按干预点分了类：约束往哪走的是正则，把旧数据混回来的是回放。本课先讲前一条：不保留任何旧数据，只在新任务的损失上加一项惩罚，把优化按在一个对旧任务仍然友好的区域里。这是 EWC（Elastic Weight Consolidation）及其后继的共同形状。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最朴素的约束是对旧解 \\(\\theta^\\*\\) 做对称的 L2 锚定：\\(\\sum_i(\\theta_i-\\theta_i^\\*)^2\\)。它对所有参数一视同仁，错在两处：对旧任务无关紧要的参数也被钉死，新任务学不动；真正要害的参数只被钉得和无关参数一样紧。旧任务的能力不均匀地分布在参数上，约束也必须不均匀。缺口因此是：在没有任何旧数据的前提下，给每个参数估一个重要性权重。</p><h3 id="重要性从哪来" tabindex="-1">重要性从哪来 <a class="header-anchor" href="#重要性从哪来" aria-label="Permalink to &quot;重要性从哪来&quot;">​</a></h3><p>EWC 用 Fisher 信息：在旧解处采样，梯度平方的期望 \\(F_i=\\mathbb{E}[(\\partial L/\\partial\\theta_i)^2]\\) 近似二阶曲率的对角项。损失变成</p> \\[L(\\theta)=L_{\\text{new}}(\\theta)+\\frac{\\lambda}{2}\\sum_i F_i(\\theta_i-\\theta_i^\\*)^2. \\]<p>Synaptic Intelligence（Zenke 等 2017）不另采样，直接在线累积训练路径上「损失降了多少、参数走了多远」，得到逐参数贡献。MAS（Aljundi 等 2018）更省：对输出幅度做扰动敏感度，连标签都不需要，适合无监督流。Online EWC（Schwarz 等 2018）把跨任务的多个二次惩罚折成带衰减的运行重要性，防锚定项随任务数膨胀。</p>',9)),(i(),r(A,null,{default:e(()=>[B(t,{id:"mermaid-23",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%AF%8F%E4%B8%AA%E5%8F%82%E6%95%B0%E5%A4%9A%E9%87%8D%E8%A6%81%3F%22%5D%20--%3E%20EWC%5B%22EWC%3A%20%E6%97%A7%E8%A7%A3%E9%87%87%E6%A0%B7%2C%E6%A2%AF%E5%BA%A6%E5%B9%B3%E6%96%B9%3DFisher%22%5D%0A%20%20Q%20--%3E%20SI%5B%22SI%3A%20%E5%9C%A8%E7%BA%BF%E7%B4%AF%E7%A7%AF%E6%8D%9F%E5%A4%B1%E9%99%8D%E5%B9%85%C3%97%E5%8F%82%E6%95%B0%E4%BD%8D%E7%A7%BB%22%5D%0A%20%20Q%20--%3E%20MAS%5B%22MAS%3A%20%E6%89%B0%E5%8A%A8%E7%9C%8B%E8%BE%93%E5%87%BA%E6%95%8F%E6%84%9F%E5%BA%A6%2C%E5%85%8D%E6%A0%87%E7%AD%BE%22%5D%0A%20%20EWC%20--%3E%20STORE%5B%22%E9%83%BD%E5%AD%98%20%CE%B8*%20%2B%20%E9%80%90%E5%8F%82%E6%95%B0%E9%87%8D%E8%A6%81%E6%80%A7%E5%9B%BE%22%5D%0A%20%20SI%20--%3E%20STORE%0A%20%20MAS%20--%3E%20STORE%0A%20%20STORE%20--%3E%20OE%5B%22Online%20EWC%3A%20%E8%B7%A8%E4%BB%BB%E5%8A%A1%E8%A1%B0%E5%87%8F%E6%8A%98%E7%AE%97%E9%98%B2%E8%86%A8%E8%83%80%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"Fisher 信息可以翻译成「这个参数牵一发动多少」：在旧任务的数据上抖动该参数，损失抖得越厉害，说明它对旧任务越要紧，罚项拴它的绳子就勒得越紧。注意这只是对角近似——只看每个参数单独抖动，不看参数之间的联动。")],-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"Fisher 罚项存下来等于再存一份同规模矩阵：全参语言模型上这是一倍显存与一份快照。所以 EWC 一族在中小模型或适配器上常用，全参大模型上多作为辅助项。")],-1)),a[5]||(a[5]=E("h2",{id:"方法",tabindex:"-1"},[l("方法 "),E("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),a[6]||(a[6]=E("p",null,"实现顺序：训旧任务到收敛，冻结采样一批输入估 \\(F_i\\)，存 \\(\\theta^\\*\\) 与 \\(F\\)，然后带着罚项训新任务。三个工程决策决定成败。一是 \\(\\lambda\\) 的量纲：Fisher 的尺度随任务与层剧烈变化，直接给全局 \\(\\lambda\\) 会把浅层钉死、深层放空，按层归一后再定权更稳。二是估计 \\(F\\) 的样本量：几百到几千批足够对角近似收敛，太少的重要性图噪声主导。三是多久刷新锚：任务流细碎时，每个任务都新建锚会膨胀，Online EWC 的衰减折算是默认。",-1)),(i(),r(A,null,{default:e(()=>[B(t,{id:"mermaid-36",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E4%BB%BB%E5%8A%A1%E6%94%B6%E6%95%9B%E4%BA%8E%20%CE%B81*%22%5D%20--%3E%20FISH%5B%22%E9%87%87%E6%A0%B7%E4%BC%B0%20Fisher%20F%22%5D%0A%20%20FISH%20--%3E%20PEN%5B%22%E7%BD%9A%E9%A1%B9%20%CE%BB%2F2%C2%B7F(%CE%B8-%CE%B81*)%C2%B2%22%5D%0A%20%20NEWD%5B%22%E6%96%B0%E4%BB%BB%E5%8A%A1%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20NEW%5B%22%E6%96%B0%E4%BB%BB%E5%8A%A1%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20PEN%20--%3E%20SUM%5B%22%E6%80%BB%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20NEW%20--%3E%20SUM%0A%20%20SUM%20--%3E%20OUT%5B%22%E6%96%B0%E4%BB%BB%E5%8A%A1%E5%8F%AF%E5%AD%A6%EF%BC%8C%E6%97%A7%E8%A7%A3%E8%A2%AB%E5%BC%B9%E6%80%A7%E6%8B%89%E4%BD%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">「弹性」可以想象成每根参数上拴了一根橡皮筋：重要性高的参数橡皮筋粗（\\(F\\) 大），拉远了痛感强；无关参数的橡皮筋细，随便拉。训新任务就是在拉扯与固定之间找平衡，\\(\\lambda\\) 调的是整套橡皮筋的总粗细。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>二次罚项有概率解读：把旧任务的后验用拉普拉斯近似压成以旧解为中心、精度为 Fisher 的高斯，EWC 就是在最大化新旧后验乘积。这同时暴露了它的适用域：近似只在旧解附近有效，任务链一长、参数被拉着走远，二次型对旧损失的描述就失真，遗忘重新出现——这就是任务序列上锚要更新、衰减的原理。</p><p>对角近似丢掉了参数间的耦合。真正保住旧功能有时靠两个参数的协调移动，对角 Fisher 各自都不大，罚项放行，旧功能仍然坏掉。函数空间的保护靠的是罚项在多数方向上恰好够高，这是一个经验事实而非保证，所以 EWC 的效果必须回到<a href="/llm/continual-forgetting-mechanism">上一课</a>的成绩轨迹上验收，而不是看罚项是否收敛。</p><p><span class="marginnote">初学者容易以为罚项收敛、参数没怎么动，就等于旧任务安全了。罚项约束的是参数位移，不等于功能被保住：两个参数可以各自小幅移动、组合起来却让旧功能失效，而对角 Fisher 恰好看不见这种联动。验收只能靠旧任务成绩轨迹，不能只看罚项数值。</span></p><p>\\(\\lambda\\) 是稳定性与可塑性的预算旋钮：调太大，新任务损失压不下去，模型「学会了不学」；调太小，等于没加。它没有先验答案，必须按遗忘指标与新任务成绩的联合扫描定。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>EWC 一族不解决任务边界不清的问题：重要性是按任务估计的，流式输入里任务切不开，估计窗口就切不开。它也不解决灾难性的表示漂移：惩罚的是参数位移，不是功能位移，小位移大破坏的情形保护不住。与回放的分工要分清：<a href="/llm/continual-replay">持续学习与回放</a>一课的结论是语言模型上任务间参数高度共享，「重要」几乎蔓延到整网，逐参数重要性图趋于平坦，罚项退化为温和的 L2；此时回放的数据证据更硬。工程上合理的组合是：无旧数据或数据敏感时正则独撑，有回放时正则降级为辅助。</p><p>最后是验证口径：EWC 与基线比较必须在新任务成绩与旧任务遗忘两轴同时报告，只报旧任务保持的新任务可能根本没学会——那是把可塑性赔给了稳定性，不算赢。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无旧数据时，参数正则用逐参数重要性把优化锚在旧解附近，重要性来自 Fisher、路径积分或输出敏感度。</li><li>二次罚项是旧任务后验的拉普拉斯近似，只在旧解邻域有效，任务链长必须衰减刷新。</li><li>对角近似丢耦合；参数位移不等于功能保持，验收只能回到任务成绩轨迹。</li><li>\\(\\lambda\\) 是稳定性-可塑性预算旋钮，按层归一后联合扫描，没有全局默认值。</li><li>语言模型上任务共享参数使重要性图趋平，正则常与回放组合使用。</li><li>出处：Kirkpatrick 等 2017（EWC）；Zenke 等 2017（SI）；Aljundi 等 2018（MAS）；Schwarz 等 2018（Online EWC）。</li></ul>',11))])}const f=s(p,[["render",h]]);export{_ as __pageData,f as default};
